/* Exact small-matrix determinant laboratory and subject-specific stored models. */
(() => {
'use strict';
const esc=x=>String(x).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const gcd=(a,b)=>{a=a<0n?-a:a;b=b<0n?-b:b;while(b){[a,b]=[b,a%b];}return a;};
class Q {constructor(n,d=1n){n=BigInt(n);d=BigInt(d);if(!d)throw Error('Zero divisor.');if(d<0n){n=-n;d=-d;}const g=gcd(n,d);this.n=n/g;this.d=d/g;}add(b){return new Q(this.n*b.d+b.n*this.d,this.d*b.d);}neg(){return new Q(-this.n,this.d);}sub(b){return this.add(b.neg());}mul(b){return new Q(this.n*b.n,this.d*b.d);}div(b){return new Q(this.n*b.d,this.d*b.n);}toString(){return String(this.n)+(this.d===1n?'':'/'+this.d);}num(){return Number(this.n)/Number(this.d);}}
const q=x=>new Q(x),one=q(1),zero=q(0),cp=A=>A.map(r=>r.map(v=>new Q(v.n,v.d))),values=A=>A.map(r=>r.map(String));
function determinant(A){const n=A.length;if(!n)return one;let result=zero;for(let j=0;j<n;j++){const minor=A.slice(1).map(r=>r.filter((_,k)=>k!==j));result=result.add(A[0][j].mul(determinant(minor)).mul(q(j%2?-1:1)));}return result;}
const mathNum=x=>{const a=String(x).split('/');const mn=s=>s.startsWith('-')?'<mrow><mo>−</mo><mn>'+s.slice(1)+'</mn></mrow>':'<mn>'+esc(s)+'</mn>';return a.length===2?'<mfrac>'+mn(a[0])+mn(a[1])+'</mfrac>':mn(a[0]);};
const math=s=>'<math xmlns="http://www.w3.org/1998/Math/MathML"><mrow><mi mathvariant="normal">det</mi><mi>A</mi><mo>=</mo>'+mathNum(s)+'</mrow></math>';
const tx=(x,y,s,cls='label',anchor='start')=>`<text x="${x}" y="${y}" text-anchor="${anchor}" class="det-${cls}">${esc(s)}</text>`;
const line=(x,y,u,v,c='#77939a')=>`<line x1="${x}" y1="${y}" x2="${u}" y2="${v}" stroke="${c}" stroke-width="2"/>`;
const wrap=(s,h=490)=>`<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 1000 ${h}" role="img" data-visual-type="plot">${s}</svg>`;
function grid(A,hot=-1){let s='';A.forEach((r,i)=>r.forEach((v,j)=>{const x=90+j*95,y=110+i*72;s+=`<g data-entity="cell-${i}-${j}"><rect x="${x}" y="${y}" width="82" height="58" rx="7" fill="${i===hot?'#f3deb7':'#e6efea'}" stroke="#b0c4c5"/>`+tx(x+41,y+37,v,'math','middle')+'</g>';}));return s;}
function makeFrame(m,A,factor,operation,why,hot=-1){const originalDet=m.originalDet,det=determinant(A),snapshot={matrix:values(A),factor:String(factor),determinant:String(det),originalDeterminant:String(originalDet)},previous=m.frames.at(-1)?.snapshot;
const s=tx(35,32,operation)+grid(A,hot)+tx(555,155,'Exact rational arithmetic')+tx(555,215,'det(current) = '+factor+' × det(original)','math')+tx(555,275,'det(original) = '+originalDet,'math');
m.frames.push({snapshot,svg:wrap(s,155+A.length*72),caption:why,formulaHtml:math(originalDet),teaching:{operation,why,checks:[{mathHtml:math(det),result:String(det.toString()===factor.mul(originalDet).toString())}],changes:previous?Object.keys(snapshot).filter(k=>JSON.stringify(previous[k])!==JSON.stringify(snapshot[k])).map(k=>({field:k,before:previous[k],after:snapshot[k]})):[],currentState:snapshot,initial:!previous,reading:m.invariant,guide:m.code,activeLine:previous?2:0,mode:m.kind}});}
function elimination(input){const A=input.map(r=>r.map(q));const m={id:'editable',title:'Exact elimination of your supplied matrix',kind:'editable-exact-row-elimination',invariant:'Inputs are exact integers; every rational quotient is retained. Only row replacements and swaps are used. A failed pivot search explicitly establishes singularity.',code:['Search the current pivot column in remaining rows.','Swap a nonzero candidate into the pivot slot if needed.','Subtract an exact multiple of the pivot row.','Multiply final diagonal entries and correct swap parity.'],frames:[],originalDet:determinant(A)};let factor=one;
makeFrame(m,A,factor,'Initialize the actual input matrix','No matrix entry has been changed.');
for(let k=0;k<A.length;k++){let p=k;while(p<A.length&&!A[p][k].n)p++;if(p===A.length){makeFrame(m,A,factor,'No nonzero pivot remains in column '+(k+1),'The unprocessed pivot column is zero; rank is below the order and determinant is zero.');break;}
if(p!==k){[A[k],A[p]]=[A[p],A[k]];factor=factor.neg();makeFrame(m,A,factor,'Swap rows '+(k+1)+' and '+(p+1),'A row swap reverses the determinant sign; the original value remains fixed.',k);}
for(let i=k+1;i<A.length;i++){if(!A[i][k].n)continue;const c=A[i][k].div(A[k][k]);A[i]=A[i].map((v,j)=>v.sub(c.mul(A[k][j])));makeFrame(m,A,factor,'R'+(i+1)+' becomes R'+(i+1)+' minus ('+c+') R'+(k+1),'The exact replacement clears one below-pivot entry and preserves the determinant.',i);}}
makeFrame(m,A,factor,'Read the triangular endpoint','Multiply its diagonal and account for swaps. The separately expanded determinant supplies an independent exact check.');m.result={determinant:String(m.originalDet)};delete m.originalDet;return m;}
function geometry(input){if(input.length!==2)throw Error('Oriented area uses exactly a two-by-two matrix.');if(input.flat().some(x=>Math.abs(x)>4))throw Error('Area mode uses entries from −4 to 4 to preserve the fixed coordinate scale.');const m={id:'editable',title:'Oriented area of your supplied columns',kind:'editable-oriented-area',invariant:'Coordinates and scale stay fixed; column order determines orientation. The last specialization makes the second column twice the first to show collapse.',code:['Read the two actual columns.','Inspect their signed parallelogram.','Exchange columns and check sign reversal.','Replace the second by twice the first and inspect collapse.'],frames:[]};for(const [k,A]of [input,[[input[0][1],input[0][0]],[input[1][1],input[1][0]]],[[input[0][0],2*input[0][0]],[input[1][0],2*input[1][0]]]].entries()){
const det=determinant(A.map(r=>r.map(q))),u=[A[0][0],A[1][0]],v=[A[0][1],A[1][1]],P=([x,y])=>[485+25*x,300-25*y],o=P([0,0]),a=P(u),b=P(v),c=P([u[0]+v[0],u[1]+v[1]]);let s=tx(35,32,m.title)+line(125,300,855,300)+line(485,60,485,570)+`<g data-entity="area"><polygon points="${o} ${a} ${c} ${b}" fill="#dcebe3" stroke="#518a78" stroke-width="2"/></g>`;for(const [id,t,col]of[['u',a,'#9b673d'],['v',b,'#3c728d']])s+=`<g data-entity="edge-${id}">`+line(...o,...t,col)+`<circle cx="${t[0]}" cy="${t[1]}" r="5" fill="${col}"/></g>`;s+=tx(60,625,'u = ('+u+'); v = ('+v+'); signed area = '+det,'math');const snapshot={matrix:A,determinant:String(det),specialization:k===2};const why=k===0?'This is your actual input.':k===1?'Columns are exchanged; this is a derived configuration of your input.':'Explicit derived specialization: v = 2u. It is not an additional premise about the original matrix.';m.frames.push({snapshot,svg:wrap(s,680),caption:why,formulaHtml:math(det),teaching:{operation:['Read input','Exchange columns','Make columns dependent'][k],why,checks:[{mathHtml:math(det),result:k===2?'true':String(det.n!==0n)}],changes:[],currentState:snapshot,initial:k===0,reading:m.invariant,guide:m.code,activeLine:k,mode:m.kind}});}m.result={determinant:m.frames[0].snapshot.determinant};return m;}
const controls=()=>'<div class="det-controls"><button type="button" data-reset>Restart</button><button type="button" data-prev>Previous</button><button type="button" data-play>Play</button><button type="button" data-next>Next</button><label>Speed<select data-speed><option value="2600">Slow</option><option value="1800" selected>Normal</option><option value="1300">Fast</option></select></label><label>Step<input type="range" data-seek min="0" value="0"></label></div><div class="det-stage"></div><p class="det-caption"></p><p data-progress></p><div class="det-formula formula-block"></div><div class="det-print"></div>';
function mount(host,m){const stage=host.querySelector('.det-stage');const p=TeachingTransitions.raw({host,model:m,stage,caption:host.querySelector('.det-caption'),formula:host.querySelector('.det-formula'),seek:host.querySelector('[data-seek]'),progress:host.querySelector('[data-progress]'),play:host.querySelector('[data-play]'),speed:host.querySelector('[data-speed]'),prev:host.querySelector('[data-prev]'),next:host.querySelector('[data-next]'),reset:host.querySelector('[data-reset]'),printRoot:host.querySelector('.det-print')});
// Geometry interpolates actual coordinates, keeping every edge attached. Arithmetic
// checkpoints remain discrete; highlighting changes explain those exact operations.
let last=stage.querySelector('svg').cloneNode(true),lastSvg=stage.querySelector('svg');
function morph(old){const svg=stage.querySelector('svg');if(!svg)return;svg.getAnimations({subtree:true}).forEach(a=>a.cancel());if(matchMedia('(prefers-reduced-motion: reduce)').matches)return;
const geometric=/oriented|parallelogram|reflection-vector|subspace-volume|quadratic-form-direction/.test(m.kind),pairs=[];
for(const g of svg.querySelectorAll('[data-entity]')){const prev=[...old.querySelectorAll('[data-entity]')].find(x=>x.dataset.entity===g.dataset.entity);if(!prev)continue;
if(geometric){const a=[...prev.querySelectorAll('line,circle,polygon,text')],b=[...g.querySelectorAll('line,circle,polygon,text')];b.forEach((node,i)=>{if(!a[i]||a[i].tagName!==node.tagName)return;for(const attr of['x','y','x1','x2','y1','y2','cx','cy','points']){const av=a[i].getAttribute(attr),bv=node.getAttribute(attr);if(av===null||bv===null||av===bv)continue;const aa=av.split(/[ ,]+/).map(Number),bb=bv.split(/[ ,]+/).map(Number);if(aa.length===bb.length&&aa.every(Number.isFinite)&&bb.every(Number.isFinite))pairs.push({node,attr,a:aa,b:bb,target:bv});}});}else{const a=prev.querySelector('rect'),b=g.querySelector('rect');if(a&&b&&a.getAttribute('fill')!==b.getAttribute('fill'))b.animate([{fill:a.getAttribute('fill')},{fill:b.getAttribute('fill')}],{duration:700});if(prev.textContent!==g.textContent)g.querySelectorAll('text').forEach(t=>t.animate([{opacity:.25},{opacity:1}],{duration:700}));}}
if(!pairs.length)return;const proxy=document.createElementNS(svg.namespaceURI,'rect');proxy.setAttribute('width','1');proxy.setAttribute('height','1');proxy.setAttribute('opacity','0');svg.append(proxy);const animation=proxy.animate([{opacity:0},{opacity:0}],{duration:1000,easing:'linear'});const label=document.createElementNS(svg.namespaceURI,'text');label.setAttribute('x','35');label.setAttribute('y','64');label.setAttribute('class','det-label');label.textContent='Transition preview; numerical checks describe the target checkpoint.';svg.append(label);
function tick(){if(!svg.isConnected||animation.playState==='idle')return;const t=Math.min(1,Number(animation.currentTime||0)/1000),u=t*t*(3-2*t);for(const p of pairs)p.node.setAttribute(p.attr,p.a.map((v,i)=>v+(p.b[i]-v)*u).join(' '));if(t<1)requestAnimationFrame(tick);else{for(const p of pairs)p.node.setAttribute(p.attr,p.target);label.remove();}}requestAnimationFrame(tick);}
for(const name of['next','prev']){const button=host.querySelector('[data-'+name+']'),original=button.onclick;button.onclick=event=>{const old=stage.querySelector('svg').cloneNode(true);original(event);morph(old);last=stage.querySelector('svg').cloneNode(true);lastSvg=stage.querySelector('svg');};}
new MutationObserver(()=>{const now=stage.querySelector('svg');if(now===lastSvg)return;if(host.dataset.running==='true')morph(last);last=now.cloneNode(true);lastSvg=now;}).observe(stage,{childList:true});return p;}
const api={Q,determinant,elimination,geometry};if(typeof module!=='undefined'){module.exports=api;return;}globalThis.DeterminantModels=api;
async function boot(){const data=await(await fetch('l_det-models.json')).json();globalThis.DeterminantPlayers=[];for(const host of document.querySelectorAll('[data-det-model]')){const m=data.models.find(x=>x.id===host.dataset.detModel);if(!m)throw Error('Missing determinant model.');DeterminantPlayers.push(mount(host,m));}
const form=document.querySelector('#det-form'),out=document.querySelector('#det-output'),error=document.querySelector('#det-error');let current=null;form.addEventListener('submit',event=>{event.preventDefault();try{const raw=form.elements.matrix.value.trim(),rows=raw.split(';').map(r=>r.split(',').map(v=>v.trim()));if(rows.length<2||rows.length>4||rows.some(r=>r.length!==rows.length)||rows.flat().some(x=>!/^[-+]?\d+$/.test(x)||Math.abs(Number(x))>20))throw Error('Use a square matrix of order 2–4, with integer entries from −20 to 20. Separate columns with commas and rows with semicolons.');const A=rows.map(r=>r.map(Number)),m=form.elements.kind.value==='area'?geometry(A):elimination(A);current?.pause();current?.teaching.root.remove();out.innerHTML='<section class="det-model" tabindex="0"><h3>'+esc(m.title)+'</h3><p>'+esc(m.invariant)+'</p>'+controls()+'</section>';current=mount(out.firstChild,m);globalThis.DeterminantLab=current;error.textContent='';}catch(err){error.textContent=err.message;}});}
boot().catch(err=>{const p=document.createElement('p');p.setAttribute('role','alert');p.textContent='The interactive laboratory could not initialize: '+err.message;document.querySelector('.lesson').prepend(p);throw err;});
})();
